import Foundation
import UIKit

// =====================================================================
//  DEMO PATIENT SEED (demo only) — 3 real fundus photos run through our
//  actual AI pipeline (YOLO ROI detector + U-Net++ segmentation), not a
//  random mock. `hasGlaucoma`/`cdr` are the model's own output, matching
//  raport_wynikow_diagnozy.txt from the dataset run. Kept deliberately
//  small (a couple hundred KB) after a much larger version (29 patients,
//  ~2.5MB of embedded base64) made Swift Playgrounds hang on load.
//
//  `imageBase64` is the cropped ROI with the classic disc/cup overlay.
//  `maskBase64` is the cropped grayscale disc/cup mask (comparison
//  screen's "Maski" mode). `rawImageBase64` is the same crop WITHOUT the
//  overlay — used only to recognize a matching photo picked live during
//  a demo (see ImageFingerprint.swift), never shown directly.
//
//  Base64 is wrapped to short lines on purpose — one multi-hundred-KB
//  single line was itself enough to choke the editor/compiler.
// =====================================================================

struct DemoSeedPatient {
    let code: String
    let hasGlaucoma: Bool
    let cdr: Double
    let confidence: Double
    let avatarKind: AvatarKind
    let avatarTint: AvatarTint
    let imageBase64: String
    let maskBase64: String
    let rawImageBase64: String
}

extension DemoSeedPatient {
    /// Base64 strings are stored line-wrapped for editor/compiler friendliness;
    /// strip the newlines back out before decoding.
    var cleanImageBase64: String { imageBase64.filter { !$0.isNewline } }
    var cleanMaskBase64: String { maskBase64.filter { !$0.isNewline } }
    var cleanRawImageBase64: String { rawImageBase64.filter { !$0.isNewline } }

    var decodedImage: UIImage? { Data(base64Encoded: cleanImageBase64).flatMap { UIImage(data: $0) } }
    var decodedMaskImage: UIImage? { Data(base64Encoded: cleanMaskBase64).flatMap { UIImage(data: $0) } }
    var decodedRawImage: UIImage? { Data(base64Encoded: cleanRawImageBase64).flatMap { UIImage(data: $0) } }
}

/// Two distinct dataset photos combined into one demo patient with two
/// visits, purely to exercise the analysis-comparison slider with real
/// (not hand-drawn) images. Not an actual longitudinal case.
struct DemoComparisonSeed {
    let patientCode: String
    let avatarKind: AvatarKind
    let avatarTint: AvatarTint
    let older: DemoSeedPatient
    let newer: DemoSeedPatient
}

